export function translator(language) {
  const singular = {issueCount: 'oneIssue', topicCount: 'oneTopic'};
  return (key, values = {}) => {
    const name = values.count === 1 ? (singular[key] ?? key) : key;
    return (copy[name]?.[language === 'en' ? 1 : 0] ?? name)
      .replace(/\{(\w+)\}/g, (_, field) => values[field] ?? '');
  };
}
